hooks.command:
python3 -c "import sys,json
try:
    d=json.load(sys.stdin)
    p=str(d.get('tool_input',{}).get('prompt',''))
    if '[EPISTEMIC-DISCIPLINE' in p or '[EPISTEMIC-EXEMPT:' in p:
        sys.exit(0)
    sys.stderr.write('BLOCKED by epistemic-preamble-guard: subagent prompt lacks the [EPISTEMIC-DISCIPLINE v1] preamble. Prepend the block from skills/epistemic-discipline/discipline-preamble.md to the prompt, or tag the spawn [EPISTEMIC-EXEMPT: <reason>] if it is a trivial mechanical agent (pure search/fetch, no claims).')
    sys.exit(2)
except SystemExit:
    raise
except Exception:
    sys.exit(0)
"
